changeSet.sql:
ALTER TABLE nexus.topics DROP CONSTRAINT topics_parent_fk;

ALTER TABLE nexus.topics
    ADD CONSTRAINT fk_topics_parent_tenant
    FOREIGN KEY (tenant_id, parent_id)
    REFERENCES nexus.topics (tenant_id, id)
    ON DELETE SET NULL
    NOT VALID;

ALTER TABLE nexus.topics NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_cross_tenant_count BIGINT;
BEGIN
    SELECT count(*) INTO v_cross_tenant_count
      FROM nexus.topics t
     WHERE t.parent_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM nexus.topics p
            WHERE p.id = t.parent_id
              AND p.tenant_id = t.tenant_id
       );
    IF v_cross_tenant_count > 0 THEN
        RAISE EXCEPTION 'RDR-194 D4 (nexus-tk070.p5a): % cross-tenant nexus.topics.parent_id reference(s) found -- this is data CORRUPTION, not a population to remediate silently. Remedy: quarantine the offending row(s), report them, and re-run taxonomy assignment for the affected tenant(s) (assignments are derived data, RDR-194 D1). The fk_topics_parent_tenant repoint is BLOCKED until this count is zero. ENUMERATE (requires BYPASSRLS/superuser -- nexus_svc and nexus_admin are NOBYPASSRLS and this query must see every tenant row, the same access gap blocking cloud-count-5 itself, nexus-tk070.cc5): SELECT t.tenant_id, t.id, t.parent_id, p.tenant_id AS parent_tenant_id FROM nexus.topics t JOIN nexus.topics p ON p.id = t.parent_id WHERE t.parent_id IS NOT NULL AND p.tenant_id != t.tenant_id;', v_cross_tenant_count;
    END IF;
    RAISE NOTICE 'RDR-194 D4 (nexus-tk070.p5a): 0 cross-tenant nexus.topics.parent_id references found -- fk_topics_parent_tenant repoint proceeding.';
END $$;

ALTER TABLE nexus.topics FORCE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_topics_parent_tenant') THEN
        ALTER TABLE nexus.topics VALIDATE CONSTRAINT fk_topics_parent_tenant;
    END IF;
END $$;

ALTER TABLE nexus.topic_assignments DROP CONSTRAINT topic_assignments_topic_id_fkey;

ALTER TABLE nexus.topic_assignments
    ADD CONSTRAINT fk_topic_assignments_topic_tenant
    FOREIGN KEY (tenant_id, topic_id)
    REFERENCES nexus.topics (tenant_id, id)
    ON DELETE CASCADE
    NOT VALID;

ALTER TABLE nexus.topic_assignments NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.topics NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_cross_tenant_count BIGINT;
BEGIN
    SELECT count(*) INTO v_cross_tenant_count
      FROM nexus.topic_assignments a
     WHERE NOT EXISTS (
           SELECT 1 FROM nexus.topics t
            WHERE t.id = a.topic_id
              AND t.tenant_id = a.tenant_id
       );
    IF v_cross_tenant_count > 0 THEN
        RAISE EXCEPTION 'RDR-194 D4 (nexus-tk070.p5a): % cross-tenant nexus.topic_assignments.topic_id reference(s) found -- this is data CORRUPTION, not a population to remediate silently. Remedy: quarantine the offending row(s), report them, and re-run taxonomy assignment for the affected tenant(s) (assignments are derived data, RDR-194 D1). The fk_topic_assignments_topic_tenant repoint is BLOCKED until this count is zero. ENUMERATE (requires BYPASSRLS/superuser -- nexus_svc and nexus_admin are NOBYPASSRLS and this query must see every tenant row, the same access gap blocking cloud-count-5 itself, nexus-tk070.cc5): SELECT a.tenant_id, a.doc_id, a.topic_id, t.tenant_id AS topic_tenant_id FROM nexus.topic_assignments a JOIN nexus.topics t ON t.id = a.topic_id WHERE t.tenant_id != a.tenant_id;', v_cross_tenant_count;
    END IF;
    RAISE NOTICE 'RDR-194 D4 (nexus-tk070.p5a): 0 cross-tenant nexus.topic_assignments.topic_id references found -- fk_topic_assignments_topic_tenant repoint proceeding.';
END $$;

ALTER TABLE nexus.topics FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.topic_assignments FORCE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_topic_assignments_topic_tenant') THEN
        ALTER TABLE nexus.topic_assignments VALIDATE CONSTRAINT fk_topic_assignments_topic_tenant;
    END IF;
END $$;

ALTER TABLE nexus.topic_links DROP CONSTRAINT topic_links_from_topic_id_fkey;

ALTER TABLE nexus.topic_links
    ADD CONSTRAINT fk_topic_links_from_topic_tenant
    FOREIGN KEY (tenant_id, from_topic_id)
    REFERENCES nexus.topics (tenant_id, id)
    ON DELETE CASCADE
    NOT VALID;

ALTER TABLE nexus.topic_links NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.topics NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_cross_tenant_count BIGINT;
BEGIN
    SELECT count(*) INTO v_cross_tenant_count
      FROM nexus.topic_links l
     WHERE NOT EXISTS (
           SELECT 1 FROM nexus.topics t
            WHERE t.id = l.from_topic_id
              AND t.tenant_id = l.tenant_id
       );
    IF v_cross_tenant_count > 0 THEN
        RAISE EXCEPTION 'RDR-194 D4 (nexus-tk070.p5a): % cross-tenant nexus.topic_links.from_topic_id reference(s) found -- this is data CORRUPTION, not a population to remediate silently. Remedy: quarantine the offending row(s), report them, and re-run taxonomy assignment for the affected tenant(s) (assignments are derived data, RDR-194 D1). The fk_topic_links_from_topic_tenant repoint is BLOCKED until this count is zero. ENUMERATE (requires BYPASSRLS/superuser -- nexus_svc and nexus_admin are NOBYPASSRLS and this query must see every tenant row, the same access gap blocking cloud-count-5 itself, nexus-tk070.cc5): SELECT l.tenant_id, l.from_topic_id, l.to_topic_id, t.tenant_id AS from_topic_tenant_id FROM nexus.topic_links l JOIN nexus.topics t ON t.id = l.from_topic_id WHERE t.tenant_id != l.tenant_id;', v_cross_tenant_count;
    END IF;
    RAISE NOTICE 'RDR-194 D4 (nexus-tk070.p5a): 0 cross-tenant nexus.topic_links.from_topic_id references found -- fk_topic_links_from_topic_tenant repoint proceeding.';
END $$;

ALTER TABLE nexus.topics FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.topic_links FORCE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_topic_links_from_topic_tenant') THEN
        ALTER TABLE nexus.topic_links VALIDATE CONSTRAINT fk_topic_links_from_topic_tenant;
    END IF;
END $$;

ALTER TABLE nexus.topic_links DROP CONSTRAINT topic_links_to_topic_id_fkey;

ALTER TABLE nexus.topic_links
