            WHERE t.id = l.to_topic_id
              AND t.tenant_id = l.tenant_id
       );
    IF v_cross_tenant_count > 0 THEN
        RAISE EXCEPTION 'RDR-194 D4 (nexus-tk070.p5a): % cross-tenant nexus.topic_links.to_topic_id reference(s) found -- this is data CORRUPTION, not a population to remediate silently. Remedy: quarantine the offending row(s), report them, and re-run taxonomy assignment for the affected tenant(s) (assignments are derived data, RDR-194 D1). The fk_topic_links_to_topic_tenant repoint is BLOCKED until this count is zero. ENUMERATE (requires BYPASSRLS/superuser -- nexus_svc and nexus_admin are NOBYPASSRLS and this query must see every tenant row, the same access gap blocking cloud-count-5 itself, nexus-tk070.cc5): SELECT l.tenant_id, l.from_topic_id, l.to_topic_id, t.tenant_id AS to_topic_tenant_id FROM nexus.topic_links l JOIN nexus.topics t ON t.id = l.to_topic_id WHERE t.tenant_id != l.tenant_id;', v_cross_tenant_count;
    END IF;
    RAISE NOTICE 'RDR-194 D4 (nexus-tk070.p5a): 0 cross-tenant nexus.topic_links.to_topic_id references found -- fk_topic_links_to_topic_tenant repoint proceeding.';
END $$;

ALTER TABLE nexus.topics FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.topic_links FORCE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_topic_links_to_topic_tenant') THEN
        ALTER TABLE nexus.topic_links VALIDATE CONSTRAINT fk_topic_links_to_topic_tenant;
    END IF;
END $$;
